export type CreateArtifactUploadData = {
    /**
     * The artifact to add a version to (a draft is made without it) and the distinct files, each with its SHA-256 in lower-case hex and its size.
     */
    body: CreateArtifactUploadRequest;
    headers?: {
        /**
         * The id of the organization the request acts in. Required when the signed-in person is a member of several organizations; without it, a person with exactly one active membership acts in that organization. Missing while several memberships are active, 409 `org_required` (`error.type`, the usual `ApiError` body); an organization the person is not a member of, 404, as for anything of another organization. A token bound to one organization (device, agent, runner, service key) acts in its own organization.
         */
        'Ostrom-Org'?: string;
    };
    path?: never;
    query?: never;
    url: '/api/v1/artifacts/uploads';
};

export type CreateArtifactUploadErrors = {
    /**
     * Not 1 to 200 files, a SHA-256 that is not 64 lower-case hexadecimal characters, a negative size, or one SHA-256 announced with two sizes (`invalid_request`). Also: the body is not the expected JSON object (`invalid_request`).
     */
    400: ApiError;
    /**
     * No credential, or an unknown, expired or revoked one (`unauthorized`).
     */
    401: ApiError;
    /**
     * The credential lacks `artifacts:write`, or the caller does not own the artifact (`forbidden`). Also: the credential may not call this operation (`forbidden`).
     */
    403: ApiError;
    /**
     * No such artifact, or one the caller may not read, or no organization for the caller (`not_found`).
     */
    404: ApiError;
    /**
     * Artifacts are not active (`artifact_storage_missing`, `artifact_storage_unverified` or `artifacts_disabled`), the artifact's files are being cleaned up and `Retry-After` says when to try again (`artifact_busy`), or a new artifact would put the owner over `quotaArtifactsPerMember` (`artifact_quota_exceeded`).
     */
    409: ApiError;
    /**
     * A file over 16 MiB (`artifact_file_too_large`).
     */
    413: ApiError;
    /**
     * The caller holds 16 open uploads or 20 unpublished drafts (`artifact_uploads_busy`).
     */
    429: ApiError;
    /**
     * An unexpected server error (`internal_error`). Retry later.
     */
    500: ApiError;
    /**
     * Any other error, in the same envelope.
     */
    default: ApiError;
};

export type CreateArtifactUploadError = CreateArtifactUploadErrors[keyof CreateArtifactUploadErrors];

