export type AnswerGovernanceConfirmationData = {
    /**
     * The answer: `confirm` or `refuse`.
     */
    body: AnswerConfirmationRequest;
    headers?: {
        /**
         * The id of the organization the request acts in. Required when the signed-in person is a member of several organizations; without it, a person with exactly one active membership acts in that organization. Missing while several memberships are active, 409 `org_required` (`error.type`, the usual `ApiError` body); an organization the person is not a member of, 404, as for anything of another organization. A token bound to one organization (device, agent, runner, service key) acts in its own organization.
         */
        'Ostrom-Org'?: string;
    };
    path: {
        /**
         * The confirmation's id.
         */
        id: string;
    };
    query?: never;
    url: '/api/v1/confirmations/{id}/answer';
};

export type AnswerGovernanceConfirmationErrors = {
    /**
     * An `answer` that is neither `confirm` nor `refuse` (`invalid_request`). Also: the body is not the expected JSON object (`invalid_request`).
     */
    400: ApiError;
    /**
     * No credential, or an unknown, expired or revoked one (`unauthorized`).
     */
    401: ApiError;
    /**
     * A token, or a member who is neither an owner nor an admin (`forbidden`), or a sign-in more than 5 minutes old for `confirm` (`step_up_required`). Also: the credential may not call this operation (`forbidden`).
     */
    403: ApiError;
    /**
     * No such confirmation in the caller's organization, or one the caller may not read (`not_found`).
     */
    404: ApiError;
    /**
     * Already answered (`confirmation_closed`), what it replaces changed since it was asked (`confirmation_stale`), or the confirmed write's own error (key `error.type`).
     */
    409: ApiError;
    /**
     * It expired unanswered (`confirmation_expired`).
     */
    410: ApiError;
    /**
     * An unexpected server error (`internal_error`). Retry later.
     */
    500: ApiError;
    /**
     * Any other error, in the same envelope.
     */
    default: ApiError;
};

export type AnswerGovernanceConfirmationError = AnswerGovernanceConfirmationErrors[keyof AnswerGovernanceConfirmationErrors];

export type AnswerGovernanceConfirmationResponses = {
    /**
     * The answered confirmation; when confirmed, `result` holds what the write returned.
     */
    200: ConfirmationDto;
};

export type AnswerGovernanceConfirmationResponse = AnswerGovernanceConfirmationResponses[keyof AnswerGovernanceConfirmationResponses];

